CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TYPE "Role" AS ENUM ('ADMIN', 'RECEPTIONIST');
CREATE TYPE "AppointmentStatus" AS ENUM ('CONFIRMED', 'CANCELLED');
CREATE TABLE "User" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'RECEPTIONIST',"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ NOT NULL,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Doctor" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"specialization" TEXT NOT NULL,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ NOT NULL,CONSTRAINT "Doctor_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Patient" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"phone" TEXT NOT NULL,"email" TEXT,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ NOT NULL,CONSTRAINT "Patient_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Appointment" ("id" TEXT NOT NULL,"doctorId" TEXT NOT NULL,"patientId" TEXT NOT NULL,"startAt" TIMESTAMPTZ NOT NULL,"endAt" TIMESTAMPTZ NOT NULL,"status" "AppointmentStatus" NOT NULL DEFAULT 'CONFIRMED',"cancellationFee" INTEGER NOT NULL DEFAULT 0,"cancelledAt" TIMESTAMPTZ,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ NOT NULL,CONSTRAINT "Appointment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ClinicSettings" ("id" INTEGER NOT NULL DEFAULT 1,"cancellationWindowMinutes" INTEGER NOT NULL DEFAULT 120,"lateCancellationFee" INTEGER NOT NULL DEFAULT 100,"timezone" TEXT NOT NULL DEFAULT 'Asia/Kolkata',"clinicDayStart" TEXT NOT NULL DEFAULT '09:00',"clinicDayEnd" TEXT NOT NULL DEFAULT '18:00',"updatedAt" TIMESTAMPTZ NOT NULL,CONSTRAINT "ClinicSettings_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE UNIQUE INDEX "Patient_phone_key" ON "Patient"("phone"); CREATE INDEX "Patient_name_idx" ON "Patient"("name"); CREATE INDEX "Appointment_doctorId_startAt_idx" ON "Appointment"("doctorId","startAt"); CREATE INDEX "Appointment_startAt_idx" ON "Appointment"("startAt"); CREATE INDEX "Appointment_status_idx" ON "Appointment"("status");
ALTER TABLE "Appointment" ADD CONSTRAINT "Appointment_doctorId_fkey" FOREIGN KEY ("doctorId") REFERENCES "Doctor"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Appointment" ADD CONSTRAINT "Appointment_patientId_fkey" FOREIGN KEY ("patientId") REFERENCES "Patient"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Appointment" ADD CONSTRAINT appointment_no_confirmed_overlap EXCLUDE USING gist ("doctorId" WITH =, tstzrange("startAt", "endAt", '[)') WITH &&) WHERE ("status" = 'CONFIRMED');
